draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 * Math.sin(t));
  ctx.lineTo(W/2 - 50, H);
  ctx.lineTo(W/2 + 50, H);
  ctx.closePath();
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
